309	// GetSeries 查询系列；不存在时返回包裹 ErrNotFound 的错误。
310	func (r *Registry) GetSeries(id string) (Series, error) {
311		r.mu.Lock()
312		defer r.mu.Unlock()
313		if err := r.checkOpen(); err != nil {
314			return Series{}, err
315		}
316		s, ok := r.state.Series[id]
317		if !ok {
318			return Series{}, fmt.Errorf("%w: 系列 %s", ErrNotFound, id)
319		}
320		return Series{ID: s.ID, CreatorID: s.CreatorID, Metadata: s.Metadata, Sealed: s.Sealed}, nil
321	}
