323	// ---- 发行 ----
324	
325	func (req IssueRequest) validatePresent() error {
326		missing := []string{}
327		if strings.TrimSpace(req.Operator) == "" {
328			missing = append(missing, "operator")
329		}
330		if strings.TrimSpace(req.Reason) == "" {
331			missing = append(missing, "reason")
332		}
333		if strings.TrimSpace(req.RequestID) == "" {
334			missing = append(missing, "request_id")
335		}
336		if strings.TrimSpace(req.ItemID) == "" {
337			missing = append(missing, "item_id")
338		}
339		if strings.TrimSpace(req.SeriesID) == "" {
340			missing = append(missing, "series_id")
341		}
342		if strings.TrimSpace(req.BatchNo) == "" {
343			missing = append(missing, "batch_no")
344		}
345		if strings.TrimSpace(req.HolderID) == "" {
346			missing = append(missing, "holder_id")
347		}
348		if len(missing) > 0 {
349			return fmt.Errorf("%w: 发行请求缺少必填字段 %s", ErrInvalidArgument, strings.Join(missing, ", "))
350		}
351		return nil
352	}
353	
354	func issueParamsSig(req IssueRequest) string {
355		b, _ := json.Marshal(struct {
356			Kind     string `json:"kind"`
357			ItemID   string `json:"item_id"`
358			SeriesID string `json:"series_id"`
359			BatchNo  string `json:"batch_no"`
360			Metadata string `json:"metadata"`
361			HolderID string `json:"holder_id"`
362			Reason   string `json:"reason"`
363		}{"issue", req.ItemID, req.SeriesID, req.BatchNo, req.Metadata, req.HolderID, req.Reason})
364		return string(b)
365	}
366	
367	// Issue 发行一件藏品。成功后持有版本为 1，初始持有人为 req.HolderID。
368	// 操作者必须是系列创建账户且可用，初始持有人必须已登记且可用，系列未
369	// 封存，藏品编号从未使用过。同一 (操作者, 请求号) 且业务参数相同的
370	// 重复提交返回首次结果；参数不同返回 ErrRequestConflict。
371	//
372	// 状态类拒绝的落盘失败时，与整批发行一致：返回保存错误（保留实际写入
373	// 错误）而非该业务错误，结果为空（无藏品编号、无持有人、无版本、无历史
374	// 序号、业务错误为空、不标回放），请求号不被这次未保存的拒绝占用；保存
375	// 条件恢复后用完全相同的请求重提，按当时的业务状态重新判断：拒绝条件仍
376	// 在则重新保存此次拒绝并返回对应业务错误，状态已变为满足请求则正常发行。
377	func (r *Registry) Issue(req IssueRequest) (IssueResult, error) {
378		if err := req.validatePresent(); err != nil {
379			return IssueResult{}, err
380		}
381		r.mu.Lock()
382		defer r.mu.Unlock()
383		if err := r.checkOpen(); err != nil {
384			return IssueResult{}, err
385		}
386	
387		key := requestKey(req.Operator, req.RequestID)
388		sig := issueParamsSig(req)
389		if prev, ok := r.state.Requests[key]; ok {
390			return r.replayIssue(prev, sig)
391		}
392	
393		bizErr := r.checkIssue(req)
394		if bizErr != nil {
395			if !isValidationErr(bizErr) {
396				// 状态类业务拒绝（封存、停用、无权、编号已用等）占用请求号并
397				// 落盘：相同参数重提永远返回这一次拒绝，即使状态后来变化。
398				r.state.Requests[key] = request{
399					Operator: req.Operator, RequestID: req.RequestID, Kind: "issue",
400					Params: sig, Rejected: true, Reason: errCode(bizErr),
401					ItemID: req.ItemID,
402				}
403				if err := r.commit(); err != nil {
404					// 拒绝结果落盘失败：这次拒绝没有被记住，与整批发行一致——
405					// 不能只用业务错误掩盖保存错误，调用者稍后用原请求重提时
406					// 必须按当时状态重新判断，而不是回放一个实际没有保存的
407					// 拒绝。commit 失败时已按磁盘内容重建状态，请求记录随之
408					// 撤销；此处再删一次以覆盖磁盘暂时不可读、状态未能重建
409					// 的情形。整体返回空结果：无藏品编号、无持有人、无版本、
410					// 无历史序号、不标回放、结果中业务错误为空，error 保留
411					// 实际写入错误。
412					delete(r.state.Requests, key)
413					return IssueResult{}, err
414				}
415			}
416			// 校验类错误（引用不存在等）不占用请求号，也不改变任何状态。
417			return IssueResult{ItemID: req.ItemID, Err: bizErr}, bizErr
418		}
419	
420		seq := r.state.NextSeq + 1
421		r.state.NextSeq = seq
422		r.state.Items[req.ItemID] = item{
423			ID: req.ItemID, SeriesID: req.SeriesID, BatchNo: req.BatchNo,
424			Metadata: req.Metadata, IssuedTxID: seq,
425		}
426		r.state.Holdings[req.ItemID] = holding{ItemID: req.ItemID, OwnerID: req.HolderID, Version: 1}
427		r.state.History = append(r.state.History, historyEntry{
428			Seq: seq, Kind: "issue", ItemID: req.ItemID, Operator: req.Operator,
429			Reason: req.Reason, RequestID: req.RequestID,
430			FromID: "", ToID: req.HolderID, FromVersion: 0, ToVersion: 1,
431		})
432		r.state.Requests[key] = request{
433			Operator: req.Operator, RequestID: req.RequestID, Kind: "issue",
434			Params: sig, ItemID: req.ItemID, ToID: req.HolderID, Version: 1, TxSeq: seq,
435		}
436		if err := r.commit(); err != nil {
437			return IssueResult{}, err
438		}
439		return IssueResult{ItemID: req.ItemID, OwnerID: req.HolderID, Version: 1, TxSeq: seq}, nil
440	}
441	
442	// checkIssue 按单件发行的优先级执行与整批共用的发行资格规则：参数合法
443	// 后，操作者的登记/停用问题优先于系列问题，系列问题内部依次为不存在、
444	// 已封存、操作者不是创建账户，藏品编号已占用又优先于初始持有人问题。
445	func (r *Registry) checkIssue(req IssueRequest) error {
446		return r.checkSingleIssueEligibility(req.Operator, req.SeriesID, req.ItemID, req.HolderID)
447	}
448	
449	func (r *Registry) replayIssue(prev request, sig string) (IssueResult, error) {
450		if prev.Kind != "issue" || prev.Params != sig {
451			return IssueResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
452				ErrRequestConflict, prev.Operator, prev.RequestID)
453		}
454		res := IssueResult{ItemID: prev.ItemID, OwnerID: prev.ToID, Version: prev.Version,
455			TxSeq: prev.TxSeq, Replayed: true}
456		if prev.Rejected {
457			res.Err = codeErr(prev.Reason)
458			return res, res.Err
459		}
460		return res, nil
461	}
