466		missing := []string{}
467		if strings.TrimSpace(req.Operator) == "" {
468			missing = append(missing, "operator")
469		}
470		if strings.TrimSpace(req.Reason) == "" {
471			missing = append(missing, "reason")
472		}
473		if strings.TrimSpace(req.RequestID) == "" {
474			missing = append(missing, "request_id")
475		}
476		if strings.TrimSpace(req.ItemID) == "" {
477			missing = append(missing, "item_id")
478		}
479		if strings.TrimSpace(req.ExpectedOwner) == "" {
480			missing = append(missing, "expected_owner")
481		}
482		if strings.TrimSpace(req.ToID) == "" {
483			missing = append(missing, "to_id")
484		}
485		if req.ExpectedVer <= 0 {
486			missing = append(missing, "expected_version")
487		}
