694	// ---- 限时一次性代转授权 ----
695	
696	// authzCurrentStatus 计算授权当前状态。撤销与使用是落盘的终态；到期不
697	// 落盘，按当前时间实时判断——从到期时间点起即视为已过期。
698	func authzCurrentStatus(a authzRec, now time.Time) string {
699		switch a.Status {
700		case "revoked":
701			return AuthRevoked
702		case "used":
703			return AuthUsed
704		}
705		if !a.ExpiresAt.IsZero() && !now.Before(a.ExpiresAt) {
706			return AuthExpired
707		}
708		return AuthActive
709	}
