752	func createAuthzParamsSig(req CreateAuthorizationRequest) string {
753		// Price 用 omitempty：价款为 0 时签名与旧格式一致，旧授权创建请求
754		// 仍可回放；改价则按请求号冲突拒绝。
755		b, _ := json.Marshal(struct {
756			Kind          string `json:"kind"`
757			AuthID        string `json:"auth_id"`
758			ItemID        string `json:"item_id"`
759			TrusteeID     string `json:"trustee_id"`
760			ToID          string `json:"to_id"`
761			ExpectedOwner string `json:"expected_owner"`
762			ExpectedVer   int64  `json:"expected_version"`
763			ExpiresAt     string `json:"expires_at"`
764			Price         int64  `json:"price,omitempty"`
765			Reason        string `json:"reason"`
766		}{"auth_create", req.AuthID, req.ItemID, req.TrusteeID, req.ToID,
767			req.ExpectedOwner, req.ExpectedVer,
768			req.ExpiresAt.UTC().Format(time.RFC3339Nano), req.Price, req.Reason})
769		return string(b)
770	}
771	
772	// CreateAuthorization 由当前持有人为一件已发行藏品创建限时、一次性的
773	// 代转授权：指定唯一授权编号、受托账户、固定接收账户、绝对到期时间，
774	// 以及期望持有人与期望版本。授权绑定创建时的持有版本，不改变持有关系，
775	// 也不限制持有人继续直接转让。受托人不能是授权人；受托人可与接收人
776	// 相同，但接收人也不能是授权人。到期时间必须晚于当前时间。
777	//
778	// 请求号与发行、转让共用同一操作者的请求号范围：相同业务参数重提返回
779	// 首次结果（成功或状态类业务拒绝），参数变化返回 ErrRequestConflict；
780	// 参数错误与引用不存在不占用请求号。
781	//
782	// 成功与状态类拒绝都以保存完成为准：本次结果尚未写入原登记册而保存失败
783	// （如数据位置暂时无法写入）时，返回实际保存错误，不报告创建成功，也不
784	// 只返回原业务拒绝；结果为空（授权编号与状态为空、绑定版本为零、不标
785	// 回放、业务错误为空），error 说明保存失败。即使失败后原数据暂时无法
786	// 读取、状态未能按磁盘重建，这次操作也不留下任何新增授权、创建记录或
787	// 请求号占用，授权历史序号不被消耗，后续其他操作成功保存也不会把这次
788	// 未保存的内容带进登记册。保存条件恢复后用完全相同的请求重提，按当时
789	// 的业务状态重新判断：拒绝条件仍在则重新保存此次拒绝并返回对应业务
790	// 错误（首次重提不标回放），状态已满足请求则正常创建。
791	func (r *Registry) CreateAuthorization(req CreateAuthorizationRequest) (CreateAuthorizationResult, error) {
792		if err := req.validatePresent(); err != nil {
793			return CreateAuthorizationResult{}, err
794		}
795		r.mu.Lock()
796		defer r.mu.Unlock()
797		if err := r.checkOpen(); err != nil {
798			return CreateAuthorizationResult{}, err
799		}
800	
801		now := r.now()
802		key := requestKey(req.Operator, req.RequestID)
803		sig := createAuthzParamsSig(req)
804		if prev, ok := r.state.Requests[key]; ok {
805			return r.replayCreateAuthz(prev, sig)
806		}
807	
808		if bizErr := r.checkCreateAuthorization(req, now); bizErr != nil {
809			if !isValidationErr(bizErr) {
810				// 状态类业务拒绝（编号占用、停用、同人、版本不符、到期时间
811				// 已过等）占用请求号并落盘；参数错误与引用不存在不占用。
812				r.state.Requests[key] = request{
813					Operator: req.Operator, RequestID: req.RequestID, Kind: "auth_create",
814					Params: sig, Rejected: true, Reason: errCode(bizErr),
815					AuthID: req.AuthID, ItemID: req.ItemID,
816				}
817				if err := r.commit(); err != nil {
818					// 拒绝结果落盘失败：这次拒绝没有被记住，与发行、转让一致——
819					// 不能只用业务错误掩盖保存错误，调用者稍后用原请求重提时
820					// 必须按当时状态重新判断，而不是回放一个实际没有保存的
821					// 拒绝。commit 失败时已按磁盘内容重建状态，请求记录随之
822					// 撤销；此处再删一次以覆盖磁盘暂时不可读、状态未能重建
823					// 的情形。整体返回空结果：授权编号与状态为空、绑定版本
824					// 为零、不标回放、结果中业务错误为空，error 保留实际
825					// 写入错误。
826					delete(r.state.Requests, key)
827					return CreateAuthorizationResult{}, err
828				}
829			}
830			return CreateAuthorizationResult{AuthID: req.AuthID, Err: bizErr}, bizErr
831		}
832	
833		h := r.state.Holdings[req.ItemID]
834		a := authzRec{
835			ID: req.AuthID, ItemID: req.ItemID, GranterID: req.Operator,
836			TrusteeID: req.TrusteeID, ToID: req.ToID, ExpiresAt: req.ExpiresAt,
837			GrantVer: h.Version, Price: req.Price, CreatedAt: now,
838		}
839		// 回滚基点：保存失败且磁盘暂时不可读、状态未能按磁盘重建时，本次
840		// 未保存的授权、创建记录与请求号占用都必须显式撤销，否则后续任何
841		// 一次成功保存都会把这份未保存的授权带进登记册。
842		prevAuthSeq := r.state.NextAuthSeq
843		prevEvents := len(r.state.AuthEvents)
844		r.state.Authzs[req.AuthID] = a
845		authSeq := prevAuthSeq + 1
846		r.state.NextAuthSeq = authSeq
847		r.state.AuthEvents = append(r.state.AuthEvents, authzEvent{
848			Seq: authSeq, AuthID: req.AuthID, ItemID: req.ItemID, Kind: "create",
849			Operator: req.Operator, Reason: req.Reason, RequestID: req.RequestID,
850			FromStatus: "", ToStatus: AuthActive, OccurredAt: now,
851		})
852		r.state.Requests[key] = request{
853			Operator: req.Operator, RequestID: req.RequestID, Kind: "auth_create",
854			Params: sig, AuthID: req.AuthID, ItemID: req.ItemID, Version: h.Version,
855		}
856		if err := r.commit(); err != nil {
857			// commit 失败时已尝试按磁盘内容重建状态：重建成功则本次改动已
858			// 随旧状态整体撤销（请求记录不存在），无需再动；磁盘暂时不可读、
859			// 状态未能重建时请求记录仍在，据此把本次未保存的改动全部撤销。
860			if _, ok := r.state.Requests[key]; ok {
861				delete(r.state.Requests, key)
862				delete(r.state.Authzs, req.AuthID)
863				r.state.AuthEvents = r.state.AuthEvents[:prevEvents]
864				r.state.NextAuthSeq = prevAuthSeq
865			}
866			return CreateAuthorizationResult{}, err
867		}
868		return CreateAuthorizationResult{AuthID: req.AuthID, Status: AuthActive, GrantVer: h.Version}, nil
869	}
