871	func (r *Registry) checkCreateAuthorization(req CreateAuthorizationRequest, now time.Time) error {
872		h, ok := r.state.Holdings[req.ItemID]
873		if !ok {
874			if _, itemExists := r.state.Items[req.ItemID]; !itemExists {
875				return fmt.Errorf("%w: 藏品 %s", ErrNotFound, req.ItemID)
876			}
877			return fmt.Errorf("%w: 藏品 %s 没有持有记录", ErrNotFound, req.ItemID)
878		}
879		op, ok := r.state.Accounts[req.Operator]
880		if !ok {
881			return fmt.Errorf("%w: 授权人账户 %s", ErrNotFound, req.Operator)
882		}
883		trustee, ok := r.state.Accounts[req.TrusteeID]
884		if !ok {
885			return fmt.Errorf("%w: 受托人账户 %s", ErrNotFound, req.TrusteeID)
886		}
887		to, ok := r.state.Accounts[req.ToID]
888		if !ok {
889			return fmt.Errorf("%w: 接收账户 %s", ErrNotFound, req.ToID)
890		}
891		if req.TrusteeID == req.Operator {
892			return fmt.Errorf("%w: 受托人不能是授权人 %s", ErrSameAccount, req.Operator)
893		}
894		if req.ToID == req.Operator {
895			return fmt.Errorf("%w: 接收人不能是授权人 %s", ErrSameAccount, req.Operator)
896		}
897		if !op.Active {
898			return fmt.Errorf("%w: 授权人账户 %s", ErrAccountInactive, req.Operator)
899		}
900		if !trustee.Active {
901			return fmt.Errorf("%w: 受托人账户 %s", ErrAccountInactive, req.TrusteeID)
902		}
903		if !to.Active {
904			return fmt.Errorf("%w: 接收账户 %s", ErrAccountInactive, req.ToID)
905		}
906		// 授权编号占用是对象级冲突，优先于当前时间与持有版本检查。
907		if _, exists := r.state.Authzs[req.AuthID]; exists {
908			return fmt.Errorf("%w: 授权编号 %s 已被占用", ErrAlreadyExists, req.AuthID)
909		}
910		// 到期时间不晚于当前时间即为参数错误；从到期时间点起不可使用。
911		if !req.ExpiresAt.After(now) {
912			return fmt.Errorf("%w: 到期时间 %s 必须晚于当前时间",
913				ErrInvalidArgument, req.ExpiresAt.Format(time.RFC3339Nano))
914		}
915		if h.OwnerID != req.ExpectedOwner || h.Version != req.ExpectedVer ||
916			req.Operator != h.OwnerID {
917			return fmt.Errorf("%w: 藏品 %s 当前为 %s 版本 %d",
918				ErrConflict, req.ItemID, h.OwnerID, h.Version)
919		}
920		return nil
921	}
