923	func (r *Registry) replayCreateAuthz(prev request, sig string) (CreateAuthorizationResult, error) {
924		if prev.Kind != "auth_create" || prev.Params != sig {
925			return CreateAuthorizationResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
926				ErrRequestConflict, prev.Operator, prev.RequestID)
927		}
928		res := CreateAuthorizationResult{AuthID: prev.AuthID, GrantVer: prev.Version,
929			Status: AuthActive, Replayed: true}
930		if prev.Rejected {
931			res.Err = codeErr(prev.Reason)
932			return res, res.Err
933		}
934		return res, nil
935	}
