946	// RevokeAuthorization 撤销一份尚未使用的代转授权。仅授权人可以撤销
947	// （非授权人返回 ErrForbidden）；已使用的授权不能撤销
948	// （ErrAuthorizationUsed）。授权已撤销时再次撤销不新增授权变更记录，按
949	// 成功返回。到期但未使用的授权仍可撤销（变更记录从 expired 记为
950	// revoked）。请求号语义与其他操作一致。
951	//
952	// 无权（ErrForbidden）与已使用（ErrAuthorizationUsed）两类业务拒绝同样
953	// 需要落盘：拒绝结果尚未写入原登记册而保存失败（如数据位置暂时无法写入）
954	// 时，返回实际保存错误，不能只返回上述业务错误让调用者误以为拒绝结果已经
955	// 记住；结果为空（无授权编号、无状态、业务错误为空、不标回放），error 保留
956	// 保存失败的原因。这次未保存的拒绝不改变授权内容、授权变更记录、藏品当前
957	// 持有人和版本，也不占用操作者的本次请求号——即使保存失败后原登记册数据
958	// 暂时无法读取、状态未能按磁盘重建，未保存的拒绝也不能留在当前已打开的
959	// 登记册中，或随之后另一次正常操作被保存下来。保存条件恢复后用同一操作者、
960	// 请求号、授权编号和原因重新提交，按当时的授权情况重新处理：拒绝条件仍存在
961	// 时先成功保存此次拒绝再返回相应业务错误（首次重提不标回放），此后完全相同
962	// 的提交才回放它；失败保存的请求不适用请求号冲突规则，该操作者用同号撤销另
963	// 一份自己有权撤销的授权时不会遭遇请求号冲突。必填内容缺失及授权不存在仍
964	// 直接按原错误拒绝、不占用请求号，不因当前无法保存而变成保存错误。
965	//
966	// 撤销成功同样以保存完成为准：授权状态、撤销时间、撤销记录、授权历史序号
967	// 与请求结果都尚未写入原登记册而保存失败时，返回实际保存错误而非撤销成功，
968	// 结果为空（无授权编号、无状态、业务错误为空、不标回放）。即使失败后原数据
969	// 暂时无法读取、状态未能按磁盘重建，这份撤销也必须从当前仍打开的登记册中
970	// 整体撤销：保留撤销前的授权内容与撤销时间，不新增撤销记录，授权历史序号与
971	// 请求号都不被消耗；藏品的持有人、版本以及此前已保存的其他授权和历史原样
972	// 保留，随后另一次正常操作成功保存也不会把这份未保存的撤销一并写入。失败后
973	// 能否代转仍按原规则判断：持有版本未变、相关账户可用且未到期时受托人仍能
974	// 正常使用；已到期或藏品已易手则继续返回相应业务拒绝，不能为恢复撤销前状态
975	// 让旧授权重新可用。保存条件恢复后用同一操作者、授权编号、原因和请求号再次
976	// 撤销，按此时的授权处理而不回放那次未保存的成功：授权仍未使用且允许撤销时
977	// 本次才完成撤销并新增一条记录（记录本次生效的时间、操作者、原因与前后状态，
978	// 不标回放），再原样提交才回放这一已保存结果。仅授权人能撤销、已使用授权
979	// 拒绝撤销、已撤销授权再次撤销不新增记录的既有行为不变；这些已经保存的终态
980	// 不被本次失败恢复。
981	func (r *Registry) RevokeAuthorization(req RevokeAuthorizationRequest) (RevokeAuthorizationResult, error) {
982		missing := []string{}
983		if strings.TrimSpace(req.Operator) == "" {
984			missing = append(missing, "operator")
985		}
986		if strings.TrimSpace(req.Reason) == "" {
987			missing = append(missing, "reason")
988		}
989		if strings.TrimSpace(req.RequestID) == "" {
990			missing = append(missing, "request_id")
991		}
992		if strings.TrimSpace(req.AuthID) == "" {
993			missing = append(missing, "auth_id")
994		}
995		if len(missing) > 0 {
996			return RevokeAuthorizationResult{}, fmt.Errorf("%w: 撤销授权请求缺少必填字段 %s",
997				ErrInvalidArgument, strings.Join(missing, ", "))
998		}
999		r.mu.Lock()
1000		defer r.mu.Unlock()
1001		if err := r.checkOpen(); err != nil {
1002			return RevokeAuthorizationResult{}, err
1003		}
1004	
1005		now := r.now()
1006		key := requestKey(req.Operator, req.RequestID)
1007		sig := revokeAuthzParamsSig(req)
1008		if prev, ok := r.state.Requests[key]; ok {
1009			return r.replayRevokeAuthz(prev, sig)
1010		}
1011	
1012		a, ok := r.state.Authzs[req.AuthID]
1013		if !ok {
1014			// 引用不存在不占用请求号。
1015			err := fmt.Errorf("%w: 授权 %s", ErrNotFound, req.AuthID)
1016			return RevokeAuthorizationResult{AuthID: req.AuthID, Err: err}, err
1017		}
1018		if a.GranterID != req.Operator {
1019			bizErr := fmt.Errorf("%w: 只有授权人 %s 可以撤销授权 %s",
1020				ErrForbidden, a.GranterID, req.AuthID)
1021			if err := r.recordRevokeRejection(key, sig, req, bizErr); err != nil {
1022				return RevokeAuthorizationResult{}, err
1023			}
1024			return RevokeAuthorizationResult{AuthID: req.AuthID, Err: bizErr}, bizErr
1025		}
1026		switch authzCurrentStatus(a, now) {
1027		case AuthUsed:
1028			bizErr := fmt.Errorf("%w: 授权 %s 已使用，不能撤销", ErrAuthorizationUsed, req.AuthID)
1029			if err := r.recordRevokeRejection(key, sig, req, bizErr); err != nil {
1030				return RevokeAuthorizationResult{}, err
1031			}
1032			return RevokeAuthorizationResult{AuthID: req.AuthID, Err: bizErr}, bizErr
1033		case AuthRevoked:
1034			// 已撤销是幂等终态：不新增授权变更记录；该请求号仍登记为成功，
1035			// 相同请求重放回放同一结果。
1036			r.state.Requests[key] = request{
1037				Operator: req.Operator, RequestID: req.RequestID, Kind: "auth_revoke",
1038				Params: sig, AuthID: req.AuthID,
1039			}
1040			if err := r.commit(); err != nil {
1041				// 请求结果落盘失败：这次重放登记没有被记住，与撤销成功路径一致——
1042				// 显式撤销尚未保存的请求号占用，覆盖磁盘暂时不可读、状态未能按磁盘
1043				// 重建的情形，返回空结果与实际保存错误。已撤销终态本就存在于磁盘，
1044				// 无需回滚授权本身。
1045				delete(r.state.Requests, key)
1046				return RevokeAuthorizationResult{}, err
1047			}
1048			return RevokeAuthorizationResult{AuthID: req.AuthID, Status: AuthRevoked}, nil
1049		}
1050	
1051		// 回滚基点：撤销以一次保存完成为准。记录撤销前的授权记录、授权历史
1052		// 长度与历史序号，保存失败且磁盘暂时不可读、状态未能按磁盘重建时据此
1053		// 整体撤销，否则这份未保存的撤销会留在当前已打开的登记册中（授权显示
1054		// 已撤销、受托人被拒绝代转、重复撤销被幂等分支直接放行），并随之后另
1055		// 一次成功保存夹带落盘，原请求重提也会被误当成已保存成功直接回放。
1056		prevAuthz := a
1057		prevAuthSeq := r.state.NextAuthSeq
1058		prevEvents := len(r.state.AuthEvents)
1059		from := AuthActive
1060		if authzCurrentStatus(a, now) == AuthExpired {
1061			from = AuthExpired
1062		}
1063		a.Status = "revoked"
1064		a.RevokedAt = now
1065		r.state.Authzs[req.AuthID] = a
1066		authSeq := prevAuthSeq + 1
1067		r.state.NextAuthSeq = authSeq
1068		r.state.AuthEvents = append(r.state.AuthEvents, authzEvent{
1069			Seq: authSeq, AuthID: req.AuthID, ItemID: a.ItemID, Kind: "revoke",
1070			Operator: req.Operator, Reason: req.Reason, RequestID: req.RequestID,
1071			FromStatus: from, ToStatus: AuthRevoked, OccurredAt: now,
1072		})
1073		r.state.Requests[key] = request{
1074			Operator: req.Operator, RequestID: req.RequestID, Kind: "auth_revoke",
1075			Params: sig, AuthID: req.AuthID,
1076		}
1077		if err := r.commit(); err != nil {
1078			// commit 失败时已尝试按磁盘内容重建状态：重建成功则本次改动已随
1079			// 旧状态整体撤销（授权仍未撤销、无本次撤销记录、请求记录不存在、
1080			// 序号未消耗），写回的记录与磁盘一致，无需再动；磁盘暂时不可读、
1081			// 状态未能重建时本次改动仍在，据此把这份未保存的撤销全部撤销，让
1082			// 当前已打开的登记册回到提交前状态——授权内容与撤销时间恢复原样，
1083			// 持有版本未变且账户可用、未到期时受托人仍可正常使用该授权；也不
1084			// 被随后另一次成功保存带入。返回实际写入错误而非成功或业务拒绝，
1085			// 结果为空：无授权编号、无状态、不标回放、结果中业务错误为空。
1086			if _, pending := r.state.Requests[key]; pending {
1087				delete(r.state.Requests, key)
1088				r.state.AuthEvents = r.state.AuthEvents[:prevEvents]
1089				r.state.NextAuthSeq = prevAuthSeq
1090				r.state.Authzs[req.AuthID] = prevAuthz
1091			}
1092			return RevokeAuthorizationResult{}, err
1093		}
1094		return RevokeAuthorizationResult{AuthID: req.AuthID, Status: AuthRevoked}, nil
1095	}
1096	
1097	// recordRevokeRejection 登记撤销授权的状态类业务拒绝（非授权人的
1098	// ErrForbidden、授权人撤销已使用授权的 ErrAuthorizationUsed）并落盘。
1099	// 拒绝结果以保存完成为准：落盘失败时显式撤销尚未保存的请求号占用并返回
1100	// 实际保存错误，调用方必须返回空结果与该错误，不能只返回业务拒绝让调用者
1101	// 误以为拒绝已经记住；落盘成功时返回 nil，由调用方返回业务拒绝本身。
1102	func (r *Registry) recordRevokeRejection(key, sig string, req RevokeAuthorizationRequest, bizErr error) error {
1103		r.state.Requests[key] = request{
1104			Operator: req.Operator, RequestID: req.RequestID, Kind: "auth_revoke",
1105			Params: sig, Rejected: true, Reason: errCode(bizErr), AuthID: req.AuthID,
1106		}
1107		if err := r.commit(); err != nil {
1108			// commit 失败时已尝试按磁盘内容重建状态，请求记录随之撤销；此处再
1109			// 删一次以覆盖磁盘暂时不可读、状态未能重建的情形——未保存的拒绝
1110			// 不能留在当前已打开的登记册中，也不能随随后另一次正常操作被保存。
1111			delete(r.state.Requests, key)
1112			return err
1113		}
1114		return nil
1115	}
1116	
1117	func (r *Registry) replayRevokeAuthz(prev request, sig string) (RevokeAuthorizationResult, error) {
1118		if prev.Kind != "auth_revoke" || prev.Params != sig {
1119			return RevokeAuthorizationResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
1120				ErrRequestConflict, prev.Operator, prev.RequestID)
1121		}
1122		res := RevokeAuthorizationResult{AuthID: prev.AuthID, Status: AuthRevoked, Replayed: true}
1123		if prev.Rejected {
1124			res.Err = codeErr(prev.Reason)
1125			res.Status = ""
1126			return res, res.Err
1127		}
1128		return res, nil
1129	}
1130	
1131	func proxyTransferParamsSig(req ProxyTransferRequest) string {
1132		b, _ := json.Marshal(struct {
1133			Kind   string `json:"kind"`
1134			AuthID string `json:"auth_id"`
1135			Reason string `json:"reason"`
1136		}{"proxy_transfer", req.AuthID, req.Reason})
1137		return string(b)
1138	}
1139	
1140	// ProxyTransfer 由受托人凭授权发起一次性代转。藏品与接收人均以授权
1141	// 记载为准，请求本身不能指定。成功后持有人变为授权中的接收人、持有
1142	// 版本加一，授权记为已使用并关联该笔转让；代转同样出现在藏品历史中，
1143	// 操作者记为实际受托账户并可通过授权编号追溯。
1144	//
1145	// 非受托人（ErrForbidden）、授权已撤销（ErrAuthorizationRevoked）、
1146	// 已到期（ErrAuthorizationExpired）、已使用（ErrAuthorizationUsed）、
1147	// 任一相关账户停用（ErrAccountInactive）以及持有版本已变化
1148	// （ErrConflict，即使藏品回到授权人手中也不恢复）分别明确拒绝，拒绝
1149	// 不改变持有或授权状态。成功代转用原请求号重放时，即使授权已到期、
1150	// 账户已停用或藏品再次易手，仍返回首次的转让结果。
1151	//
1152	// 上述状态类拒绝以保存完成为准：拒绝结果尚未写入原登记册而保存失败（如
1153	// 数据位置暂时无法写入）时，返回实际保存错误，不能只返回到期、无权或停用
1154	// 等业务拒绝让调用者误以为这次拒绝已经记住；结果为空（不带授权或藏品编号、
1155	// 不带转让和金额信息、不标回放，结果内的业务错误也为空），error 保留实际
1156	// 写入失败原因。这次未保存的拒绝不改变授权内容、使用标记、授权变更记录，
1157	// 也不改变藏品持有人、版本、转让历史与版税应付，并不占用操作者的本次请求
1158	// 号——即使保存失败后原数据暂时无法读取、状态未能按磁盘重建，未保存的拒绝
1159	// 也不能留在当前已打开的登记册中，或随随后另一次成功保存被记住。保存条件
1160	// 恢复后用完全相同的请求重提，按重提时的业务状态重新判断，而不是回放失败
1161	// 时的拒绝（例如到期拒绝保存失败、授权随后被撤销时，重提返回已撤销）；这次
1162	// 重新处理若保存成功不标回放，此后原样重提才回放已保存的结果。已经成功保存
1163	// 的拒绝仍按首次结果回放，改动该请求的业务内容仍报请求号冲突；必填内容缺失
1164	// 或引用不存在沿用原错误且不占用请求号。
1165	func (r *Registry) ProxyTransfer(req ProxyTransferRequest) (ProxyTransferResult, error) {
1166		missing := []string{}
1167		if strings.TrimSpace(req.Operator) == "" {
1168			missing = append(missing, "operator")
1169		}
1170		if strings.TrimSpace(req.Reason) == "" {
1171			missing = append(missing, "reason")
1172		}
1173		if strings.TrimSpace(req.RequestID) == "" {
1174			missing = append(missing, "request_id")
1175		}
1176		if strings.TrimSpace(req.AuthID) == "" {
1177			missing = append(missing, "auth_id")
1178		}
1179		if len(missing) > 0 {
1180			return ProxyTransferResult{}, fmt.Errorf("%w: 代转请求缺少必填字段 %s",
1181				ErrInvalidArgument, strings.Join(missing, ", "))
1182		}
1183		r.mu.Lock()
1184		defer r.mu.Unlock()
1185		if err := r.checkOpen(); err != nil {
1186			return ProxyTransferResult{}, err
1187		}
1188	
1189		now := r.now()
1190		key := requestKey(req.Operator, req.RequestID)
1191		sig := proxyTransferParamsSig(req)
1192		if prev, ok := r.state.Requests[key]; ok {
1193			return r.replayProxyTransfer(prev, sig)
1194		}
1195	
1196		if bizErr := r.checkProxyTransfer(req, now); bizErr != nil {
1197			if !isValidationErr(bizErr) {
1198				// 状态类业务拒绝（无权、已撤销、已到期、已使用、停用、版本已
1199				// 变化）占用请求号并落盘：相同参数重提返回这一次拒绝。
1200				r.state.Requests[key] = request{
1201					Operator: req.Operator, RequestID: req.RequestID, Kind: "proxy_transfer",
1202					Params: sig, Rejected: true, Reason: errCode(bizErr), AuthID: req.AuthID,
1203				}
1204				if err := r.commit(); err != nil {
1205					// 拒绝结果落盘失败：这次拒绝没有被记住，与发行、转让、授权
1206					// 创建/撤销一致——不能用业务错误掩盖保存错误，调用者稍后用
1207					// 原请求重提时必须按当时状态重新判断，而不是回放一个实际没有
1208					// 保存的拒绝。此分支在写入前只动了请求记录，没有改变持有、
1209					// 授权或版税；commit 失败时已按磁盘内容重建状态，请求记录随之
1210					// 撤销，此处再删一次以覆盖磁盘暂时不可读、状态未能重建的情形。
1211					// 整体返回空结果：不带授权或藏品编号、不带转让和金额信息、不标
1212					// 回放、结果中业务错误为空，error 保留实际写入错误。
1213					delete(r.state.Requests, key)
1214					return ProxyTransferResult{}, err
1215				}
1216			}
1217			// 必填缺失、授权或账户不存在等校验错误不占用请求号，也不改变持有、
1218			// 授权状态或授权变更记录。
1219			return ProxyTransferResult{AuthID: req.AuthID, Err: bizErr}, bizErr
1220		}
1221	
1222		a := r.state.Authzs[req.AuthID]
1223		// 代转价款以授权创建时记载为准，执行时不得改价；余款归转让前持有
1224		// 人（授权人），不记给受托人。持有变化、历史、应付明细与授权使用
1225		// 状态在同一临界区内一次落盘；历史记录实际受托账户并可按授权编号
1226		// 追溯。
1227		out := r.applyTransfer(a.ItemID, a.ToID, req.Operator, req.Reason, req.RequestID, a.ID, a.Price)
1228		a.Status = "used"
1229		a.UsedTxSeq = out.seq
1230		a.UsedAt = now
1231		r.state.Authzs[a.ID] = a
1232		authSeq := r.state.NextAuthSeq + 1
1233		r.state.NextAuthSeq = authSeq
1234		r.state.AuthEvents = append(r.state.AuthEvents, authzEvent{
1235			Seq: authSeq, AuthID: a.ID, ItemID: a.ItemID, Kind: "use",
1236			Operator: req.Operator, Reason: req.Reason, RequestID: req.RequestID,
1237			FromStatus: AuthActive, ToStatus: AuthUsed, TxSeq: out.seq, OccurredAt: now,
1238		})
1239		r.state.Requests[key] = request{
1240			Operator: req.Operator, RequestID: req.RequestID, Kind: "proxy_transfer",
1241			Params: sig, AuthID: a.ID, ItemID: a.ItemID, FromID: out.fromID, ToID: a.ToID,
1242			Version: out.toVer(), TxSeq: out.seq,
1243		}
1244		if err := r.commit(); err != nil {
1245			return ProxyTransferResult{}, err
1246		}
1247		return ProxyTransferResult{AuthID: a.ID, ItemID: a.ItemID, FromID: out.fromID,
1248			ToID: a.ToID, Version: out.toVer(), TxSeq: out.seq,
1249			Price: out.royalty.Price, Payables: publicPayables(out.royalty.Payees),
1250			Remainder: out.royalty.Remainder}, nil
1251	}
1252	
1253	func (r *Registry) checkProxyTransfer(req ProxyTransferRequest, now time.Time) error {
1254		a, ok := r.state.Authzs[req.AuthID]
1255		if !ok {
1256			return fmt.Errorf("%w: 授权 %s", ErrNotFound, req.AuthID)
1257		}
1258		op, ok := r.state.Accounts[req.Operator]
1259		if !ok {
1260			return fmt.Errorf("%w: 受托人账户 %s", ErrNotFound, req.Operator)
1261		}
1262		granter, gOk := r.state.Accounts[a.GranterID]
1263		to, tOk := r.state.Accounts[a.ToID]
1264		if req.Operator != a.TrusteeID {
1265			return fmt.Errorf("%w: 账户 %s 不是授权 %s 的受托人",
1266				ErrForbidden, req.Operator, req.AuthID)
1267		}
1268		if !gOk {
1269			return fmt.Errorf("%w: 授权人账户 %s", ErrNotFound, a.GranterID)
1270		}
1271		if !tOk {
1272			return fmt.Errorf("%w: 接收账户 %s", ErrNotFound, a.ToID)
1273		}
1274		if !op.Active {
1275			return fmt.Errorf("%w: 受托人账户 %s", ErrAccountInactive, req.Operator)
1276		}
1277		if !granter.Active {
1278			return fmt.Errorf("%w: 授权人账户 %s", ErrAccountInactive, a.GranterID)
1279		}
1280		if !to.Active {
1281			return fmt.Errorf("%w: 接收账户 %s", ErrAccountInactive, a.ToID)
1282		}
1283		switch authzCurrentStatus(a, now) {
1284		case AuthRevoked:
1285			return fmt.Errorf("%w: 授权 %s", ErrAuthorizationRevoked, req.AuthID)
1286		case AuthExpired:
1287			return fmt.Errorf("%w: 授权 %s", ErrAuthorizationExpired, req.AuthID)
1288		case AuthUsed:
1289			return fmt.Errorf("%w: 授权 %s", ErrAuthorizationUsed, req.AuthID)
1290		}
1291		// 授权只在创建时绑定的持有版本上有效；版本单调递增，藏品即使回到
1292		// 授权人手中也不会回到旧版本，旧授权据此永久失效。
1293		h, ok := r.state.Holdings[a.ItemID]
1294		if !ok {
1295			return fmt.Errorf("%w: 藏品 %s 没有持有记录", ErrNotFound, a.ItemID)
1296		}
1297		if h.OwnerID != a.GranterID || h.Version != a.GrantVer {
1298			return fmt.Errorf("%w: 藏品 %s 当前为 %s 版本 %d，授权绑定 %s 版本 %d",
1299				ErrConflict, a.ItemID, h.OwnerID, h.Version, a.GranterID, a.GrantVer)
1300		}
1301		return nil
1302	}
1303	
1304	func (r *Registry) replayProxyTransfer(prev request, sig string) (ProxyTransferResult, error) {
1305		if prev.Kind != "proxy_transfer" || prev.Params != sig {
1306			return ProxyTransferResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
1307				ErrRequestConflict, prev.Operator, prev.RequestID)
1308		}
1309		res := ProxyTransferResult{AuthID: prev.AuthID, ItemID: prev.ItemID, FromID: prev.FromID,
1310			ToID: prev.ToID, Version: prev.Version, TxSeq: prev.TxSeq, Replayed: true}
1311		if prev.Rejected {
1312			res.Err = codeErr(prev.Reason)
1313			return res, res.Err
1314		}
1315		// 回放首次成功的金额：授权到期、账户停用或藏品再次易手后仍返回
1316		// 原价款与应付明细，不重复计入。
1317		res.Price, res.Payables, res.Remainder = r.royaltyOfTx(prev.TxSeq)
1318		return res, nil
1319	}
1320	
1321	// ---- 授权查询 ----
1322	
1323	// GetAuthorization 按编号查询授权内容与撤销、使用状态。授权不存在时
1324	// 返回包裹 ErrNotFound 的错误；返回的 Status 按当前时间实时计算，
1325	// 到期但尚未终结的授权返回 AuthExpired。
1326	func (r *Registry) GetAuthorization(authID string) (Authorization, error) {
1327		r.mu.Lock()
1328		defer r.mu.Unlock()
1329		if err := r.checkOpen(); err != nil {
1330			return Authorization{}, err
1331		}
1332		a, ok := r.state.Authzs[authID]
1333		if !ok {
1334			return Authorization{}, fmt.Errorf("%w: 授权 %s", ErrNotFound, authID)
1335		}
1336		return Authorization{
1337			ID: a.ID, ItemID: a.ItemID, GranterID: a.GranterID, TrusteeID: a.TrusteeID,
1338			ToID: a.ToID, ExpiresAt: a.ExpiresAt, GrantVer: a.GrantVer, Price: a.Price,
1339			Status:    authzCurrentStatus(a, r.now()),
1340			UsedTxSeq: a.UsedTxSeq, UsedAt: a.UsedAt, CreatedAt: a.CreatedAt,
1341			RevokedAt: a.RevokedAt,
1342		}, nil
1343	}
1344	
1345	// AuthorizationHistory 按藏品查看授权变更记录（创建、撤销、使用），
1346	// 按发生先后排列；每条记录包含操作者、原因、请求号与前后状态。藏品
1347	// 不存在时返回包裹 ErrNotFound 的错误。
1348	func (r *Registry) AuthorizationHistory(itemID string) ([]AuthorizationEvent, error) {
1349		r.mu.Lock()
1350		defer r.mu.Unlock()
1351		if err := r.checkOpen(); err != nil {
1352			return nil, err
1353		}
1354		if _, ok := r.state.Items[itemID]; !ok {
1355			return nil, fmt.Errorf("%w: 藏品 %s", ErrNotFound, itemID)
1356		}
1357		out := make([]AuthorizationEvent, 0)
1358		for _, e := range r.state.AuthEvents {
1359			if e.ItemID != itemID {
1360				continue
1361			}
1362			out = append(out, AuthorizationEvent{
1363				Seq: e.Seq, AuthID: e.AuthID, ItemID: e.ItemID, Kind: e.Kind,
1364				Operator: e.Operator, Reason: e.Reason, RequestID: e.RequestID,
1365				FromStatus: e.FromStatus, ToStatus: e.ToStatus, TxSeq: e.TxSeq,
1366				OccurredAt: e.OccurredAt,
1367			})
1368		}
1369		return out, nil
1370	}
1371	
1372	// ---- 查询 ----
1373	
1374	// GetItem 查询单件藏品的静态登记信息；不存在时返回包裹 ErrNotFound 的错误。
1375	func (r *Registry) GetItem(id string) (Item, error) {
1376		r.mu.Lock()
1377		defer r.mu.Unlock()
1378		if err := r.checkOpen(); err != nil {
1379			return Item{}, err
1380		}
1381		it, ok := r.state.Items[id]
1382		if !ok {
1383			return Item{}, fmt.Errorf("%w: 藏品 %s", ErrNotFound, id)
1384		}
1385		return Item{ID: it.ID, SeriesID: it.SeriesID, BatchNo: it.BatchNo,
1386			Metadata: it.Metadata, IssuedTxID: it.IssuedTxID}, nil
1387	}
1388	
1389	// GetHolding 查询藏品当前持有状态；藏品不存在时返回包裹 ErrNotFound 的错误。
1390	func (r *Registry) GetHolding(itemID string) (Holding, error) {
1391		r.mu.Lock()
1392		defer r.mu.Unlock()
1393		if err := r.checkOpen(); err != nil {
1394			return Holding{}, err
1395		}
1396		h, ok := r.state.Holdings[itemID]
1397		if !ok {
1398			return Holding{}, fmt.Errorf("%w: 藏品 %s", ErrNotFound, itemID)
1399		}
1400		return Holding{ItemID: h.ItemID, OwnerID: h.OwnerID, Version: h.Version}, nil
1401	}
1402	
1403	// HoldingsOf 查询某账户当前持有的全部藏品。账户不存在时返回包裹
1404	// ErrNotFound 的错误；停用账户仍可正常查询。
1405	func (r *Registry) HoldingsOf(accountID string) ([]Holding, error) {
1406		r.mu.Lock()
1407		defer r.mu.Unlock()
1408		if err := r.checkOpen(); err != nil {
1409			return nil, err
1410		}
1411		if _, ok := r.state.Accounts[accountID]; !ok {
1412			return nil, fmt.Errorf("%w: 账户 %s", ErrNotFound, accountID)
1413		}
1414		out := make([]Holding, 0)
1415		for _, h := range r.state.Holdings {
1416			if h.OwnerID == accountID {
1417				out = append(out, Holding{ItemID: h.ItemID, OwnerID: h.OwnerID, Version: h.Version})
1418			}
1419		}
1420		sort.Slice(out, func(i, j int) bool { return out[i].ItemID < out[j].ItemID })
1421		return out, nil
1422	}
1423	
1424	// History 查询藏品的发行与历次成功转让，按发生先后排列。发行记录的
1425	// 前持有人为空、前版本为 0。重复提交不会产生额外历史。藏品不存在时
1426	// 返回包裹 ErrNotFound 的错误。
1427	func (r *Registry) History(itemID string) ([]HistoryEntry, error) {
1428		r.mu.Lock()
1429		defer r.mu.Unlock()
1430		if err := r.checkOpen(); err != nil {
1431			return nil, err
1432		}
1433		if _, ok := r.state.Items[itemID]; !ok {
1434			return nil, fmt.Errorf("%w: 藏品 %s", ErrNotFound, itemID)
1435		}
1436		out := make([]HistoryEntry, 0)
1437		for _, e := range r.state.History {
1438			if e.ItemID != itemID {
1439				continue
1440			}
1441			out = append(out, HistoryEntry{
1442				Seq: e.Seq, Kind: e.Kind, ItemID: e.ItemID, Operator: e.Operator,
1443				Reason: e.Reason, RequestID: e.RequestID, FromID: e.FromID, ToID: e.ToID,
1444				FromVersion: e.FromVersion, ToVersion: e.ToVersion, AuthID: e.AuthID,
1445			})
1446		}
1447		return out, nil
1448	}
1449	
1450	// ---- 幂等辅助 ----
1451	
1452	// requestKey 由完整的操作者账户编号与完整的请求号共同确定一条请求记录。
1453	// 采用 JSON 数组编码而非直接拼接：账户编号或请求号本身允许包含零字符
1454	// （U+0000）等任意字符，直接拼接会让 ("a", "b\x00c") 与 ("a\x00b", "c")
1455	// 之类不同的组合得到相同的键，导致不同账户互相占用请求号、回放别人的
1456	// 结果。JSON 编码对任意字符都无歧义，两个组成部分各自完整参与键的构成。
1457	func requestKey(operator, requestID string) string {
1458		b, _ := json.Marshal([2]string{operator, requestID})
1459		return string(b)
1460	}
1461	
1462	// isValidationErr 判定是否为请求本身不成立的错误：必填缺失，或引用了
1463	// 不存在的账户、系列、藏品。这类请求不占用请求号、不落任何记录，引用
1464	// 对象后来补建后仍可用原请求号完整执行一次；其余拒绝（封存、停用、
1465	// 版本冲突、无权、编号已用、收发同人等状态类业务拒绝）按首次结果记忆
1466	// 并回放。
1467	func isValidationErr(err error) bool {
1468		return errors.Is(err, ErrInvalidArgument) || errors.Is(err, ErrNotFound)
1469	}
1470	
1471	var errCodes = map[error]string{
1472		ErrNotFound:             "not_found",
1473		ErrAlreadyExists:        "already_exists",
1474		ErrAccountInactive:      "account_inactive",
1475		ErrSeriesSealed:         "series_sealed",
1476		ErrConflict:             "conflict",
1477		ErrSameAccount:          "same_account",
1478		ErrForbidden:            "forbidden",
1479		ErrAuthorizationRevoked: "authorization_revoked",
1480		ErrAuthorizationExpired: "authorization_expired",
1481		ErrAuthorizationUsed:    "authorization_used",
1482		ErrRoyaltyFrozen:        "royalty_frozen",
1483		ErrSplitIntentRejected:  "split_intent_rejected",
1484		ErrSplitIntentWithdrawn: "split_intent_withdrawn",
1485		ErrSplitIntentInvalid:   "split_intent_invalid",
1486		ErrSplitIntentExpired:   "split_intent_expired",
1487		ErrSplitAnswered:        "split_answered",
1488	}
1489	
1490	var codeErrs = map[string]error{
1491		"not_found":              ErrNotFound,
1492		"already_exists":         ErrAlreadyExists,
1493		"account_inactive":       ErrAccountInactive,
1494		"series_sealed":          ErrSeriesSealed,
1495		"conflict":               ErrConflict,
1496		"same_account":           ErrSameAccount,
1497		"forbidden":              ErrForbidden,
1498		"authorization_revoked":  ErrAuthorizationRevoked,
1499		"authorization_expired":  ErrAuthorizationExpired,
1500		"authorization_used":     ErrAuthorizationUsed,
1501		"royalty_frozen":         ErrRoyaltyFrozen,
1502		"split_intent_rejected":  ErrSplitIntentRejected,
1503		"split_intent_withdrawn": ErrSplitIntentWithdrawn,
1504		"split_intent_invalid":   ErrSplitIntentInvalid,
1505		"split_intent_expired":   ErrSplitIntentExpired,
1506		"split_answered":         ErrSplitAnswered,
1507	}
1508	
1509	func errCode(err error) string {
1510		for sentinel, code := range errCodes {
1511			if errors.Is(err, sentinel) {
1512				return code
1513			}
1514		}
1515		return "rejected"
1516	}
1517	
1518	func codeErr(code string) error {
1519		if e, ok := codeErrs[code]; ok {
1520			return e
1521		}
1522		return errors.New("registry: 请求曾被拒绝")
1523	}
1524

