245	// （原数据可读）后关闭重开，看到的仍是登记前状态；恢复保存后重新登记正常
246	// 落盘，而不是把一次从未保存的登记当成既成事实。
247	func TestRegisterAccountSaveFailureRetryAfterReopen(t *testing.T) {
248		dir := tempDir(t)
249		r := mustCreate(t, dir)
250		seedRegisterWorld(t, r)
251	
252		blockBatchSave(t, r)
253		err := r.RegisterAccount("dave", "元-dave")
254		assertSaveFailureError(t, err)
255		if err := r.Close(); err != nil {
256			t.Fatal(err)
257		}
258		r2, err := Open(dir)
259		if err != nil {
260			t.Fatalf("失败后原登记册必须仍能正常读取: %v", err)
261		}
262		t.Cleanup(func() { _ = r2.Close() })
263		assertDaveNotRegistered(t, r2)
264	
265		restoreBatchSave(t, r2)
266		if err := r2.RegisterAccount("dave", "元-dave-恢复后"); err != nil {
267			t.Fatalf("重开后重新登记应成功: %v", err)
268		}
269		if a, _ := r2.GetAccount("dave"); !a.Active || a.Metadata != "元-dave-恢复后" {
270			t.Fatalf("重开后登记保存成功才应存在且以本次元数据为准: %+v", a)
271		}
272	}
273	
274	// TestRegisterAccountBusinessRejectionsWhileUnwritable 保留登记入口原有约定：
275	// 空白编号返回 ErrInvalidArgument，已成功登记的编号（无论账户是否停用）返回
276	// ErrAlreadyExists 且不覆盖记录——这些业务拒绝不触发保存，数据位置恰好不可
277	// 写时也不能变成保存错误。元数据允许为空：新编号配空元数据在不可写时仍实际
278	// 尝试保存并返回保存错误、不留下账户，恢复后成功登记为空元数据的可用账户。
279	func TestRegisterAccountBusinessRejectionsWhileUnwritable(t *testing.T) {
280		r := mustCreate(t, tempDir(t))
281		seedRegisterWorld(t, r)
282	
283		blockBatchSave(t, r)
284	
285		if err := r.RegisterAccount("   ", "x"); !errors.Is(err, ErrInvalidArgument) {
286			t.Fatalf("空白编号应返回 ErrInvalidArgument，且不变成保存错误: %v", err)
287		}
288		// 可用账户的编号已占用：ErrAlreadyExists，记录不被覆盖。
289		if err := r.RegisterAccount("alice", "被覆盖的元数据"); !errors.Is(err, ErrAlreadyExists) {
290			t.Fatalf("已登记编号应返回 ErrAlreadyExists，且不变成保存错误: %v", err)
291		}
292		// 已停用账户的编号同样永久占用：ErrAlreadyExists，且停用状态不被恢复。
293		if err := r.RegisterAccount("carol", "被覆盖的元数据"); !errors.Is(err, ErrAlreadyExists) {
294			t.Fatalf("已停用账户的编号仍应返回 ErrAlreadyExists: %v", err)
295		}
296		if a, _ := r.GetAccount("alice"); a.Metadata != "元-alice" || !a.Active {
297			t.Fatalf("业务拒绝不应改动 alice 记录: %+v", a)
298		}
299		if c, _ := r.GetAccount("carol"); c.Metadata != "元-carol" || c.Active {
300			t.Fatalf("业务拒绝不应改动 carol 记录或恢复其停用: %+v", c)
301		}
302	
303		// 元数据允许为空：新编号仍须真实保存，不可写时返回当次保存错误且不留账户。
304		err := r.RegisterAccount("dave", "")
305		assertSaveFailureError(t, err)
306		if _, err := r.GetAccount("dave"); !errors.Is(err, ErrNotFound) {
307			t.Fatalf("保存失败后 dave 不应存在: %v", err)
308		}
309	
310		restoreBatchSave(t, r)
311		if err := r.RegisterAccount("dave", ""); err != nil {
312			t.Fatalf("恢复后空元数据登记应成功保存: %v", err)
313		}
314		if a, _ := r.GetAccount("dave"); !a.Active || a.Metadata != "" {
315			t.Fatalf("空元数据账户保存成功后应可用且元数据为空: %+v", a)
316		}
317	}
